// /frontend-react/src/components/TransportStatus.js (Revised CSS)

import React, { useState, useEffect } from 'react';
import { fetchDriverInfo } from '../utils/api'; 

const mockTransportNeed = 'wheelchair'; // Mock user's specific need

const NEED_EMOJIS = {
    wheelchair: { emoji: '♿', label: 'Wheelchair Access' },
    bedridden: { emoji: '🛏️', label: 'Stretcher Required' },
    slow: { emoji: '🚶', label: 'Slow Walking' },
};

function TransportStatus({ isEasyMode, goToMedicalDashboard, goToAppointmentFlow }) {
    const [driverInfo, setDriverInfo] = useState(null);

    useEffect(() => {
        const getData = async () => {
            const info = await fetchDriverInfo();
            setDriverInfo(info);
        };
        getData();
    }, []);

    if (!driverInfo) {
        return <h2 style={{fontSize: isEasyMode ? '48px' : '24px', textAlign: 'center'}}>Loading Transport Info...</h2>;
    }

    const currentNeed = NEED_EMOJIS[mockTransportNeed] || { emoji: '❓', label: 'Unknown Need' };

    const CardStyle = {
        backgroundColor: '#fff',
        padding: '20px',
        borderRadius: '10px',
        margin: '20px 0',
        boxShadow: '0 4px 10px rgba(0,0,0,0.1)',
        borderLeft: '5px solid #1A73E8', // Blue accent bar
    };

    return (
        <div style={{ padding: '20px', textAlign: 'center' }}>
            {/* Back Button */}
            <button 
                onClick={goToMedicalDashboard}
                style={{ position: 'absolute', top: '10px', left: '10px', padding: '8px 12px', fontSize: isEasyMode ? '20px' : '14px', backgroundColor: '#eee', border: '1px solid #ccc', borderRadius: '5px' }}
            >
                ⬅️ Menu
            </button>

            <h2 style={{fontSize: isEasyMode ? '40px' : '30px', margin: '10px 0 20px 0', marginTop: '40px', color: '#1A73E8'}}>Your Ride Status</h2>
            
            {/* 1. Transport Needs Card */}
            <div style={CardStyle}>
                <p style={{fontSize: isEasyMode ? '32px' : '20px', fontWeight: 'bold', margin: '0 0 10px 0', color: '#555'}}>
                    Your Need:
                </p>
                <span role="img" aria-label={currentNeed.label} style={{fontSize: isEasyMode ? '90px' : '50px', display: 'block'}}>
                    {currentNeed.emoji}
                </span>
                <p style={{fontSize: isEasyMode ? '28px' : '18px', margin: '5px 0', fontWeight: 'bold', color: '#007bff'}}>
                    {currentNeed.label}
                </p>
                <button 
                    onClick={goToAppointmentFlow}
                    style={{ padding: '10px 20px', fontSize: isEasyMode ? '24px' : '16px', backgroundColor: 'orange', color: 'white', border: 'none', borderRadius: '8px', marginTop: '10px' }}
                >
                    <span role="img" aria-label="Edit">🔄</span> Change Need
                </button>
            </div>
            
            {/* 2. Driver Info Card */}
            <div style={{...CardStyle, borderLeft: '5px solid #4CAF50'}}> {/* Green accent bar */}
                <h3 style={{fontSize: isEasyMode ? '32px' : '24px', margin: '0 0 20px 0', color: '#4CAF50'}}>Driver Assigned</h3>

                <div style={{ display: 'flex', justifyContent: 'space-around', alignItems: 'center' }}>
                    
                    {/* Driver Details */}
                    <div style={{ textAlign: 'left', fontSize: isEasyMode ? '26px' : '16px' }}>
                        <p style={{margin: '5px 0'}}>Name: **{driverInfo.name}**</p>
                        <p style={{margin: '5px 0'}}>Type: **{driverInfo.carType}**</p>
                        <p style={{margin: '5px 0'}}>Color: **{driverInfo.carColor}**</p>
                        <p style={{margin: '5px 0'}}>Plate: **{driverInfo.licensePlate}**</p>
                    </div>

                    {/* Driver Photo/Icon */}
                    <span role="img" aria-label="Driver" style={{fontSize: isEasyMode ? '100px' : '50px'}}>🧑‍✈️</span>
                </div>
            </div>

             {/* 3. Back Button (bottom action) */}
             <button 
                onClick={goToMedicalDashboard} 
                style={{ 
                    marginTop: '30px', 
                    padding: '15px 40px', 
                    fontSize: isEasyMode ? '30px' : '18px',
                    backgroundColor: '#333',
                    color: 'white',
                    border: 'none',
                    borderRadius: '10px',
                    fontWeight: 'bold'
                }}
            >
                <span role="img" aria-label="Back">⬅️</span> Back to Menu
            </button>
        </div>
    );
}

export default TransportStatus;
